// The search-index parser.
//
// The index is generated by somebody's script against somebody's bucket, arrives as JSON, and is
// then scanned on every keystroke - so it is exactly the kind of input that has to be refused
// precisely rather than tolerated vaguely. The parser's contract is the snapshot parser's: closed,
// exhaustive, positional. These tests are about the diagnostics as much as the accept/reject.

import { test } from "node:test";
import assert from "node:assert/strict";

import { DatasetTreeSearchIndexError, parseDatasetTreeSearchIndexV1 } from "../src/search-index.js";
import { completeIndex, hostileIndex, partialIndex } from "./fixtures/search-index.js";

function diagnosticsOf(input: unknown): { path: string; code: string; message: string }[] {
  try {
    parseDatasetTreeSearchIndexV1(input);
    return [];
  } catch (error) {
    assert.ok(error instanceof DatasetTreeSearchIndexError, `not a parse error: ${String(error)}`);
    return [...error.diagnostics];
  }
}

test("a well-formed index parses, and is frozen all the way down", () => {
  const index = parseDatasetTreeSearchIndexV1(completeIndex());
  assert.equal(index.schemaVersion, 1);
  assert.equal(index.complete, true);
  assert.equal(index.generatedAt, "2026-02-01T00:00:00Z");
  assert.equal(index.entries.length, 4);
  assert.ok(Object.isFrozen(index));
  assert.ok(Object.isFrozen(index.entries));
  assert.ok(Object.isFrozen(index.entries[0]));
  assert.ok(Object.isFrozen(index.entries[0]!.ancestors));
});

test("declared order is preserved exactly", () => {
  const index = parseDatasetTreeSearchIndexV1(completeIndex());
  assert.deepEqual(
    index.entries.map((e) => e.id),
    [
      "idx:reanalysis/surface/pr.zarr",
      "idx:downscaling/eur-11/tasmax.zarr",
      "idx:downscaling",
      "cat:reanalysis/surface/tas",
    ],
  );
});

test("an absent optional stays absent rather than becoming undefined-valued", () => {
  const index = parseDatasetTreeSearchIndexV1(partialIndex());
  assert.equal("generatedAt" in index, false);
  assert.equal("source" in index, false);
  assert.equal("size" in index.entries[0]!, false);
  assert.equal("ancestors" in index.entries[0]!, false);
});

test("hostile strings are data, and are accepted as data", () => {
  const index = parseDatasetTreeSearchIndexV1(hostileIndex());
  assert.equal(index.entries.length, 2);
  assert.equal(index.entries[0]!.name, "<img src=x onerror=alert(1)>.zarr");
});

test("a non-object is refused with one diagnostic at the document root", () => {
  for (const input of [null, 42, "index", [], undefined]) {
    const diagnostics = diagnosticsOf(input);
    assert.equal(diagnostics.length, 1, `accepted ${JSON.stringify(input)}`);
    assert.equal(diagnostics[0]!.path, "");
    assert.equal(diagnostics[0]!.code, "not-an-object");
  }
});

test("an unrecognised schema version is refused, and the value is quoted back", () => {
  const diagnostics = diagnosticsOf({ schemaVersion: 2, complete: true, entries: [] });
  const version = diagnostics.find((d) => d.path === "/schemaVersion");
  assert.ok(version);
  assert.equal(version.code, "invalid-value");
  assert.match(version.message, /schemaVersion: 1/);
  assert.match(version.message, /got 2/);
});

test("`complete` is required and must be a boolean - it is never defaulted", () => {
  const missing = diagnosticsOf({ schemaVersion: 1, entries: [] });
  assert.deepEqual(
    missing.map((d) => [d.path, d.code]),
    [["/complete", "missing-property"]],
  );
  const wrong = diagnosticsOf({ schemaVersion: 1, complete: "yes", entries: [] });
  assert.deepEqual(
    wrong.map((d) => [d.path, d.code]),
    [["/complete", "invalid-type"]],
  );
});

test("`entries` is required and must be an array", () => {
  assert.deepEqual(
    diagnosticsOf({ schemaVersion: 1, complete: true }).map((d) => [d.path, d.code]),
    [["/entries", "missing-property"]],
  );
  assert.deepEqual(
    diagnosticsOf({ schemaVersion: 1, complete: true, entries: {} }).map((d) => [d.path, d.code]),
    [["/entries", "invalid-type"]],
  );
});

test("an unknown property is an error, at the document and at an entry", () => {
  const diagnostics = diagnosticsOf({
    schemaVersion: 1,
    complete: true,
    refreshedAt: "now",
    entries: [{ id: "a", kind: "file", name: "a", titel: "typo" }],
  });
  assert.deepEqual(
    diagnostics.map((d) => [d.path, d.code]),
    [
      ["/refreshedAt", "unknown-property"],
      ["/entries/0/titel", "unknown-property"],
    ],
  );
});

test("every problem is reported in one pass, not just the first", () => {
  const diagnostics = diagnosticsOf({
    schemaVersion: 1,
    complete: true,
    entries: [
      { kind: "file", name: "a" },
      { id: "b", name: "b" },
      { id: "c", kind: "nope", name: "c" },
      { id: "d", kind: "file", name: "" },
      { id: "e", kind: "file", name: "e", size: -1 },
      { id: "f", kind: "file", name: "f", size: "big" },
      { id: "g", kind: "file", name: "g", path: 7 },
    ],
  });
  assert.deepEqual(
    diagnostics.map((d) => [d.path, d.code]),
    [
      ["/entries/0/id", "missing-property"],
      ["/entries/1/kind", "missing-property"],
      ["/entries/2/kind", "invalid-value"],
      ["/entries/3/name", "empty-string"],
      ["/entries/4/size", "invalid-value"],
      ["/entries/5/size", "invalid-type"],
      ["/entries/6/path", "invalid-type"],
    ],
  );
});

test("a duplicate id is refused, and the diagnostic names where it was first used", () => {
  const diagnostics = diagnosticsOf({
    schemaVersion: 1,
    complete: true,
    entries: [
      { id: "same", kind: "file", name: "one" },
      { id: "other", kind: "file", name: "two" },
      { id: "same", kind: "file", name: "three" },
    ],
  });
  assert.deepEqual(
    diagnostics.map((d) => [d.path, d.code]),
    [["/entries/2/id", "duplicate-id"]],
  );
  assert.match(diagnostics[0]!.message, /\/entries\/0/);
});

test("ancestors are validated as their own shape, with pointers into them", () => {
  const diagnostics = diagnosticsOf({
    schemaVersion: 1,
    complete: true,
    entries: [
      {
        id: "a",
        kind: "file",
        name: "a",
        ancestors: [
          { id: "r", name: "r" },
          { name: "no id" },
          "not an object",
          { id: "x", name: "x", depth: 2 },
        ],
      },
      { id: "b", kind: "file", name: "b", ancestors: {} },
    ],
  });
  assert.deepEqual(
    diagnostics.map((d) => [d.path, d.code]),
    [
      ["/entries/0/ancestors/1/id", "missing-property"],
      ["/entries/0/ancestors/2", "not-an-object"],
      ["/entries/0/ancestors/3/depth", "unknown-property"],
      ["/entries/1/ancestors", "invalid-type"],
    ],
  );
});

test("a pointer survives a key that contains `/` or `~`", () => {
  const diagnostics = diagnosticsOf({
    schemaVersion: 1,
    complete: true,
    entries: [{ id: "a", kind: "file", name: "a", "we/ird~key": 1 }],
  });
  assert.deepEqual(
    diagnostics.map((d) => d.path),
    ["/entries/0/we~1ird~0key"],
  );
});

test("the error message leads with a count and shows only the first few", () => {
  const entries = [];
  for (let i = 0; i < 9; i += 1) entries.push({ kind: "file", name: `n${i}` });
  try {
    parseDatasetTreeSearchIndexV1({ schemaVersion: 1, complete: true, entries });
    assert.fail("accepted an index with nine broken entries");
  } catch (error) {
    assert.ok(error instanceof DatasetTreeSearchIndexError);
    assert.equal(error.diagnostics.length, 9);
    assert.match(error.message, /9 problems/);
    assert.match(error.message, /and 4 more/);
  }
});
